package com.cpf.testkit;
import java.util.*; import java.util.concurrent.*; import java.util.function.Function;
public final class CpfMultiInstanceHarness<T> implements AutoCloseable { private final Map<String,T> instances=new ConcurrentHashMap<>(); private final ExecutorService executor=Executors.newVirtualThreadPerTaskExecutor(); public CpfMultiInstanceHarness<T> add(String id,T instance){instances.put(id,instance);return this;} public <R> Map<String,R> parallel(Function<T,R> action){var tasks=new LinkedHashMap<String,Future<R>>();instances.forEach((id,v)->tasks.put(id,executor.submit(()->action.apply(v))));var out=new LinkedHashMap<String,R>();tasks.forEach((id,f)->{try{out.put(id,f.get());}catch(Exception e){throw new CompletionException(e);}});return out;} public void kill(String id){instances.remove(id);} @Override public void close(){executor.close();} }
